2	"use server";
3	
4	import { createClient, createAdminClient } from '@/lib/supabase/server';
5	import { revalidatePath } from 'next/cache';
6	import { z } from 'zod';
7	import { ensureGenerationRoleExists } from './generations';
8	
9	const studentNumberRegex = /^[0-9]+$/;
10	
11	// Schema for re-syncing Discord member (for users who left and rejoined)
12	const reSyncSchema = z.object({
13	    last_name: z.string().min(1, '姓は必須です。'),
14	    first_name: z.string().min(1, '名は必須です。'),
15	});
16	
17	// Schema for updating own profile (allows changing student number)
18	const profileUpdateSchema = z.object({
19	    student_number: z.string().regex(/^[0-9]*$/, '学籍番号は半角数字で入力してください。').optional().nullable(),
20	});
21	
22	
23	// Schema for admin updating profile
24	const profileAdminUpdateSchema = z.object({
25	    last_name: z.string().min(1, '姓は必須です。'),
26	    first_name: z.string().min(1, '名は必須です。'),
27	    generation: z.coerce.number().int().min(0, '期は0以上の数字である必要があります。'),
28	    student_number: z.string().optional().nullable(),
29	    status: z.coerce.number().int().min(0).max(2),
30	    team_ids: z.array(z.string()).optional(),
31	});
32	
33	// Schema for initial registration
34	const registerSchema = z.object({
35	    last_name: z.string().min(1, '姓は必須です。'),
36	    first_name: z.string().min(1, '名は必須です。'),
37	    status: z.coerce.number().int().min(0).max(2),
38	    grade: z.coerce.number().int().min(1).max(3).optional(),
39	    student_number: z.string().regex(studentNumberRegex, '学籍番号は半角数字で入力してください。').optional().nullable(),
40	    generation: z.coerce.number().int().min(1, '期は正の整数である必要があります。').optional(),
41	    team_ids: z.array(z.string()).optional(),
42	}).refine(data => {
43	    if (data.status === 0 || data.status === 1) {
44	        return !!data.grade;
45	    }
46	    return true;
47	}, {
48	    message: '学年は必須です。',
49	    path: ['grade'],
50	}).refine(data => {
51	    if (data.status === 2) { // OB/OG
52	        return !!data.generation;
53	    }
54	    return true;
55	}, {
56	    message: '期は必須です。',
57	    path: ['generation'],
58	});
59	
60	async function checkAdmin() {
61	    const supabase = await createClient();
62	    const { data: { user } } = await supabase.auth.getUser();
63	    if (!user) throw new Error('Authentication required.');
64	
65	    const { data: admin } = await supabase.from('members').select('is_admin').eq('supabase_auth_user_id', user.id).single();
66	    if (!admin?.is_admin) throw new Error('Administrator privileges required.');
67	}
68	
69	function getAcademicYear() {
70	    const today = new Date();
71	    const year = today.getFullYear();
72	    const month = today.getMonth(); // 0-indexed (0 for January)
73	    return month >= 3 ? year : year - 1; // Academic year starts in April (month 3)
74	}
75	
76	function calculateGeneration(status: number, grade: number, academicYear: number) {
77	    if (status === 1) { // High School
78	        return 10 + (academicYear - 2025) - grade + 1;
79	    }
80	    if (status === 0) { // Junior High
81	        return 10 + (academicYear - 2025) + 4 - grade;
82	    }
83	    return null;
84	}
85	
86	async function syncDiscordRoles(discordUid: string) {
87	    const apiUrl = process.env.NEXT_PUBLIC_STEM_BOT_API_URL;
88	    const token = process.env.STEM_BOT_API_BEARER_TOKEN;
89	
90	    console.log(`[Discord Bot] Attempting to sync roles for discord_uid: ${discordUid}`);
91	
92	    if (!apiUrl || !token) {
93	        console.error('[Discord Bot] API URL or Bearer Token is not configured for Discord role sync.');
94	        return; // Don't throw error, just log and skip sync
95	    }
96	    
97	    try {
98	        const res = await fetch(`${apiUrl}/api/roles/sync`, {
99	            method: 'POST',
100	            headers: { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/json' },
101	            body: JSON.stringify({ discord_uid: discordUid }),
102	            cache: 'no-store',
103	        });
104	         if (!res.ok) {
105	            const errorText = await res.text();
106	            console.error(`[Discord Bot] Failed to sync roles for ${discordUid}. Status: ${res.status}, Body: ${errorText}`);
107	        } else {
108	            console.log(`[Discord Bot] Successfully initiated role sync for discord_uid: ${discordUid}`);
109	        }
110	    } catch (e) {
111	        console.error(`[Discord Bot] Error during role sync for ${discordUid}:`, e);
112	    }
113	}
114	
115	async function syncDiscordNickname(discordUid: string, name: string) {
116	    const apiUrl = process.env.NEXT_PUBLIC_STEM_BOT_API_URL;
117	    const token = process.env.STEM_BOT_API_BEARER_TOKEN;
118	
119	    console.log(`[Discord Bot] Attempting to update nickname for discord_uid: ${discordUid} to a name based on: "${name}"`);
120	
121	    if (!apiUrl || !token) {
122	        console.error('[Discord Bot] API URL or Bearer Token is not configured for Discord nickname sync.');
123	        return;
124	    }
125	    
126	    const body = {
127	        discord_uid: discordUid,
128	        name: name,
129	    };
130	
131	    try {
132	        const res = await fetch(`${apiUrl}/api/nickname/update`, {
133	            method: 'POST',
134	            headers: { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/json' },
135	            body: JSON.stringify(body),
136	            cache: 'no-store',
137	        });
138	        if (!res.ok) {
139	            const errorBody = await res.text();
140	            console.error(`[Discord Bot] Failed to update nickname for ${discordUid}. Status: ${res.status}, Body: ${errorBody}`);
141	        } else {
142	             console.log(`[Discord Bot] Successfully initiated nickname update for discord_uid: ${discordUid}`);
143	        }
144	    } catch(e) {
145	        console.error(`[Discord Bot] Error during nickname update for ${discordUid}:`, e);
146	    }
147	}
148	
149	export async function getMemberDisplayName(discordUid: string): Promise<string | null> {
150	    // 認証チェック
151	    const supabase = await createClient();
152	    const { data: { user } } = await supabase.auth.getUser();
153	    if (!user) return null;
154	
155	    const apiUrl = process.env.NEXT_PUBLIC_STEM_BOT_API_URL;
156	    const token = process.env.STEM_BOT_API_BEARER_TOKEN;
157	
158	    if (!apiUrl || !token || !discordUid) {
159	        console.error(`[Discord Bot] Cannot get display name. API URL, Token, or Discord UID is missing.`);
160	        return null;
161	    }
162	
163	    try {
164	        const response = await fetch(`${apiUrl}/api/nickname?discord_uid=${discordUid}`, {
165	            headers: {
166	                'Authorization': `Bearer ${token}`,
167	            },
168	            cache: 'no-store',
169	        });
170	
171	        if (!response.ok) {
172	            const errorText = await response.text();
173	            console.error(`[Discord Bot] Failed to fetch nickname for ${discordUid}: Status ${response.status}, Body: ${errorText}`);
174	            return null;
175	        }
176	        
177	        const data = await response.json();
178	        return data.name_only || null;
179	    } catch (error) {
180	        console.error(`[Discord Bot] Error fetching nickname for ${discordUid}:`, error);
181	        return null;
182	    }
183	}
184	
185	type MemberNameMap = { [key: string]: string };
186	
187	export async function getAllMemberNames(): Promise<MemberNameMap | null> {
188	    // 認証チェック
189	    const supabase = await createClient();
190	    const { data: { user } } = await supabase.auth.getUser();
191	    if (!user) return null;
192	
193	    const apiUrl = process.env.NEXT_PUBLIC_STEM_BOT_API_URL;
194	    const token = process.env.STEM_BOT_API_BEARER_TOKEN;
195	
196	    if (!apiUrl || !token) {
197	        console.error(`[getAllMemberNames] Aborting: API URL or Token is missing.`);
198	        return null;
199	    }
200	
201	    try {
202	        const response = await fetch(`${apiUrl}/api/members`, {
203	            headers: {
204	                'Authorization': `Bearer ${token}`,
205	            },
206	            cache: 'no-store',
207	        });
208	        
209	        if (!response.ok) {
210	            const responseText = await response.text();
211	            console.error(`[getAllMemberNames] Failed to fetch - Status: ${response.status}, Body: ${responseText}`);
212	            return null;
213	        }
214	        
215	        const data = await response.json();
216	        if (!data.success || !Array.isArray(data.data)) {
217	            console.error(`[getAllMemberNames] API response was not successful or data is not an array.`);
218	            return null;
219	        }
